/*
 * The Scala <-> AVFoundation contract of thicket-camera-preview-apple (#148): a live camera
 * preview over AVCaptureSession, in a UIView on iOS and an NSView on macOS, and a still from it.
 *
 * GENERATED by tools/shim-gen from thicket.tools.shim.PreviewAbi. Do not edit by hand: edit
 * tools/shim-gen/src/main/scala/thicket/tools/shim/PreviewAbi.scala and run `sbt shimGen/run`.
 * `sbt shimGen/test` fails while this file, PreviewShim.scala, PreviewShim.swift and PreviewAbi disagree.
 *
 * PUSH, ON THE MAIN THREAD ONLY. Every call is made on the main thread, and every answer is
 * delivered there; the session runs on a queue of the library's own. One session at a time.
 * The photo crosses as a path to a JPEG the library wrote: no bytes cross the boundary. The
 * camera permission is thicket-device-apple's. Facing: 0 front, 1 back. Fit: 0 contain,
 * 1 cover, 2 fill.
 */
#ifndef THICKET_PREVIEW_H
#define THICKET_PREVIEW_H

#include <stdint.h>

/* An NSView * or UIView *, as in thicket_apple.h. */
typedef void *sui_handle;
typedef void (*thk_prev_int_cb)(int64_t ctx, int32_t result);
typedef void (*thk_prev_text_cb)(int64_t ctx, const char *path);

/* --- devices ----------------------------------------------------------------- */
/* 1 if the device has a camera for `facing` (0 front, 1 back), 0 otherwise. iOS: the built-in
   wide-angle camera at that position. macOS: front is the first camera that is not on the back
   (built-in or external), back one the system reports on the back (docs/17 §17.4). */
int32_t thk_prev_has_camera(int32_t facing);

/* --- view -------------------------------------------------------------------- */
/* A new preview view, +1 retained, in no superview: a UIView or a layer-backed NSView whose layer
   is an AVCaptureVideoPreviewLayer with the gravity for `fit` (0 .resizeAspect, 1
   .resizeAspectFill, 2 .resize). It gives itself an aspect, height over width, from the frame
   as shown once a session runs in it (4:3 upright on iOS and 3:4 on macOS until then), so a
   layout that leaves its height open still gives it one. It shows nothing until
   thk_prev_start. */
sui_handle thk_prev_view_new(int32_t fit);

/* --- session ----------------------------------------------------------------- */
/* Stops the session running, if any, then starts one on the camera for `facing`, shown in
   `view` (one thk_prev_view_new made), with an AVCapturePhotoOutput for thk_prev_capture.
   Returns 1, and calls `done` once on the main thread when the session has started: with 1 if
   it is running, 0 if it could not be configured or did not start. Returns 0, calling nothing,
   when there is no such camera. The permission is the caller's to have asked first. */
int32_t thk_prev_start(sui_handle view, int32_t facing, thk_prev_int_cb done, int64_t ctx);
/* Detaches the running session from its view and stops it on the library's queue. Returns 1
   if there was one, 0 if not. A start or a capture under way is never answered after this:
   its `done` is dropped. */
int32_t thk_prev_stop(void);
/* Takes a still photo from the running session (AVCapturePhotoOutput, JPEG) and returns 1;
   `done` is called once on the main thread with the path of the JPEG written into `dir`
   (created if missing), upright, or "" if the capture or the write failed. Returns 0, calling
   nothing, when no session is running or a capture is already under way. */
int32_t thk_prev_capture(const char *dir, thk_prev_text_cb done, int64_t ctx);

/* --- testing ----------------------------------------------------------------- */
/* For self-tests: what AVFoundation itself reports. */
/* Sessions this library started that AVCaptureSession.isRunning says are running and that
   have not been stopped: 0 or 1. */
int32_t thk_prev_test_running(void);
/* Video frames delivered to the sessions' outputs since this library was loaded. */
int64_t thk_prev_test_frames(void);
/* The running camera's active format, in pixels, into `width` and `height`; 1, or 0 with none. */
int32_t thk_prev_test_size(double *width, double *height);
/* The running camera's facing, 0 front or 1 back as thk_prev_has_camera chose it; -1 with none. */
int32_t thk_prev_test_facing(void);
/* The preview layer's gravity in `view`, as a fit code (0 contain, 1 cover, 2 fill); -1 otherwise. */
int32_t thk_prev_test_gravity(sui_handle view);
/* The aspect `view` gives itself, height over width. */
double thk_prev_test_aspect(sui_handle view);

#endif
